/**
 * @author: Samuel Goodwin
 *
 * This file is used to validate PDF files that are contiguous in memory.
 *
 * A PDF file follows the general layout shown below, with some notable omissions for simplicity sake:
 *
 * --PDF version header
 * --Object 1
 * --Object 2
 * --Object 3
 * --Object N
 * --Xref Table or Stream
 * --Startxref offset incdicator
 * --PDF Footer
 *
 * There are many exceptions to this structure, most notably the fact that multiple
 * xref tables/streams including both types may be present within the same file due to
 * incremental updates. This file aims to leverage the xref tables and streams of a given
 * file, using the documented offsets of each object within the file to ensure each object
 * is located at their expected location within the file. If successful, this provides a high
 * degree of certainty that the file is uncorrupted and complete.
 */

#include "scalpel.h"
#include <stdio.h>
#include <stdlib.h>
#include <ctype.h>
#include <stdint.h>
#include <limits.h>
#include <setjmp.h>
#include <jpeglib.h>
#include <jerror.h>
#include <zlib.h>
#include <openssl/evp.h>

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wunused-variable"
#pragma GCC diagnostic ignored "-Wunused-but-set-variable"
#pragma GCC diagnostic ignored "-Wunused-function"
#pragma GCC diagnostic ignored "-Wunused-parameter"
#pragma GCC diagnostic ignored "-Wtype-limits"

// Define stream conditions
#define LENGTHNOTFOUND -1
#define INBLOCK 1
#define INNEXTBLOCK 2
#define MULTIBLOCK 3

// Define stream filters
#define NOFILTER 0
#define ZLIB 1
#define XML 2
#define JPEG 3
#define FILTERUNKNOWN -1

// Maximum number of digits parsed for an integer / byte offset. A 64-bit value
// is at most 20 decimal digits; a longer run is never a legitimate number.
// Parsers cap the copy length to this so a long attacker-controlled digit run
// cannot size an unbounded stack VLA (char temp[digit_run + 1]).
#define PDF_MAX_INT_DIGITS 20

// Bound footer lookahead to one complete indirect-object header plus leading
// whitespace. This can cross a block boundary without admitting a whole
// unrelated successor block as incremental-update evidence.
#define PDF_INCREMENTAL_OBJECT_LOOKAHEAD 64

// Preserve a short textual-whitespace suffix after %%EOF. The bound avoids
// absorbing a long run of filesystem padding or unrelated adjacent data.
#define PDF_TRAILING_WHITESPACE_LOOKAHEAD 8

// Some producers record an xref offset immediately before the object's line
// ending. Permit a short PDF-whitespace prefix while retaining full object-
// header validation at the adjusted position.
#define PDF_XREF_OFFSET_WHITESPACE_MAX 8

// Bound the PDF whitespace accepted between a declared xref-stream extent and
// its endstream keyword.
#define PDF_XREF_ENDSTREAM_WHITESPACE_MAX 8

// A validated terminal xref ends close to its footer. Keep enough headroom for
// an unusually large trailer without scanning deeply into unrelated data.
#define PDF_FOOTER_SEARCH_BYTES (UINT64_C(256) * 1024)

// Bound physically contiguous incremental-tail completion. Each accepted run
// must still pass full PDF validation before any block is committed.
#define PDF_INCREMENTAL_MAX_JOIN_BYTES (UINT64_C(256) * 1024)

// Bound the logical extent considered for a two-fragment xref stream. The
// declared stream length fixes the exact extent before any seam is tested.
#define PDF_XREF_MAX_JOIN_BYTES (UINT64_C(256) * 1024)
#define PDF_TRADITIONAL_XREF_OVERHEAD_BYTES (UINT64_C(16) * 1024)

// Byte budgets are rounded up to complete blocks at the active block size.
#define PDF_OBJECT_CONFIRM_BYTES (UINT64_C(512) * 1024)
#define PDF_STREAM_REPAIR_RUN_BYTES (UINT64_C(256) * 1024)
#define PDF_TRAILER_JOIN_BYTES (UINT64_C(8) * 1024)

// Retain the retired local-retry field limit when reading older checkpoints.
// Claimed body blocks are still unmapped by the backend at checkpoint sync.
#define PDF_BACKTRACK_MAX_REJECTIONS 16

// Define block selection modes
#define NEXTOBJECT 1
#define FINDENDSTREAM 2
#define EXTENDSTREAMFROMSTART 3
#define EXTENDSTREAMFROMEND 4

// Define candidate extension modes
#define OBJECTEXTNSION 1
#define ENDSTREAMEXTENSION 2

#define NOFRAG

#define INCOMPLETESTREAMDICT 1
/**
 * Holds the data used to do prelimary analysis of
 * Xref tables. I might merge this into another struct
 * at some point in the future.
 */
typedef struct XrefObject{
    int64_t offset;
} XrefObject;

/**
 * Holds the data necessary to check whether
 * a PDF object is at its expected location in
 * the file
 */
typedef struct Object{
    int obj_num;    // The object's identifier
    uint32_t obj_type; // 1: file offset; 2: object-stream number and index
    union {
        uint64_t obj_offset;
        struct {
            uint32_t object_index;
            uint32_t object_stream;
        };
    };
} Object;

_Static_assert(sizeof(Object) == 16, "PDF checkpoint Object layout");

/**
 * Main struct used for validation.
 * Emulates an xref table and enables
 * complete validation of an xref as part
 * of a file
 */
typedef struct XrefTables{
    Object *entries;    // An array of Objects derived from this table
    int count;          // The # of objects in this table
} XrefTables;

/* Temporary authenticated empty-password Standard Security Handler context. */
typedef struct PDFEncryptionContext {
    bool active, encrypt_metadata, aes, identity;
    const unsigned char *dictionary;
    size_t dictionary_length;
    unsigned char file_key[16];
    size_t file_key_length;
} PDFEncryptionContext;

typedef struct PDFRC4State {
    bool active;
    unsigned char bytes[256];
    unsigned i, j;
} PDFRC4State;

/**
 * Used to store information about xrefs in
 * relation to individual blocks.
 */
typedef struct XrefParameters{
    int64_t xref_start;    // Offset of start of xref
    int64_t xref_end;      // Offset of end of xref
    int8_t conditional_flag;
    int8_t xref_type;   // 0 = table, 1 = stream
} XrefParameters;

typedef struct PDFBlockState{
    int first_obj;
    XrefParameters *xref_block_data;
    int32_t num_xrefs;
} PDFBlockState;

/* Search positions use physical coordinates. The current seam
 * is retried if its decoder was interrupted; completed seams are not repeated.
 * No decoder or immutable-index pointer is serialized. */
typedef struct PDFStreamCursor {
    uint64_t key, scans[6], trials;
    int64_t tail;
    int32_t preferred_index, offset_index, split_index, seam;
    uint32_t contiguous_tried, tail_active;
} PDFStreamCursor;

/* Exhaustive negative results are disposable optimization metadata. Immutable
 * cache snapshots are shared by carve-state clones, never globally mutable.
 * Checkpoint restore deliberately starts with an empty cache. */
#define PDF_STREAM_FAILURE_LIMIT 128
#define PDF_STREAM_FAILURE_DEPENDENCIES 128

typedef struct PDFStreamFailureEntry {
    uint64_t key[2];
    uint32_t dependencies;
    /* actual * 2: backend unavailable; actual * 2 + 1: already mapped. */
    uint64_t blocked[PDF_STREAM_FAILURE_DEPENDENCIES];
} PDFStreamFailureEntry;

typedef struct PDFStreamFailureCache {
    atomic_uint references;
    uint32_t count, next;
    PDFStreamFailureEntry entries[];
} PDFStreamFailureCache;

typedef struct PDFStreamFailureProbe {
    PDFStreamFailureEntry entry;
    bool valid, exhausted;
} PDFStreamFailureProbe;

/* Search progress contains values and owned arrays only; no live blockvectors
 * or decoder pointers cross a checkpoint boundary. */
typedef struct PDFObjectOption {
    int64_t actual;
    uint8_t lookahead, probe;
} PDFObjectOption;

typedef struct PDFObjectScan {
    uint64_t key;
    int64_t next_actual;
    size_t count, capacity;
    uint8_t neighbours_done;
    PDFObjectOption *options;
} PDFObjectScan;

typedef struct PDFResume {
    int phase;
    uint64_t apparent_blocks, candidate_hash, blocks_before;
    int64_t next_block;
    int best_count, block_count, score;
    int32_t local;
    bool ambiguous;
    int64_t split_head, split_tail;
    int split_first, split_type;
    int32_t split_local;
    uint64_t probe_key;
    int64_t probe_next, probe_value;
    int64_t extension_slot;
    Object *entries;
    int64_t *blocks;
    PDFStreamCursor stream;
    PDFObjectScan object_scan;
} PDFResume;

/* Physical coordinates retain enumeration across rollback and blockmap
 * compaction. A selected proposal advances only after admission consumes it. */
typedef struct PDFXrefScanPosition {
    int64_t next_actual, marker_actual, split_actual;
    uint64_t split_next;
    int32_t marker_next, split_local, split_type;
} PDFXrefScanPosition;

typedef struct PDFWeakXrefCursor {
    uint64_t context;
    bool valid, exhausted, selected;
    PDFXrefScanPosition position, after_selected;
} PDFWeakXrefCursor;

typedef struct PDFBacktrackChoice {
    uint64_t slot;
    int64_t actual_block;
} PDFBacktrackChoice;

/* Immutable physical mapping for the longest independently checked prefix.
 * Carve-state clones share it by reference; checkpoints serialize the mapping. */
typedef struct PDFPartialPrefix {
    atomic_uint references;
    /* Runtime-only result: zero unchecked, UINT64_MAX incomplete, otherwise
     * the independently complete byte length. Never a publication decision. */
    atomic_uint_fast64_t checked_length;
    uint64_t length;
    uint64_t count;
    int64_t actual[];
} PDFPartialPrefix;

typedef struct PDFSlotDelta {
    int64_t delta;
    uint64_t slot;
} PDFSlotDelta;

typedef struct PDFRunEvidence {
    int64_t delta;
    uint64_t min_slot;
    uint64_t max_slot;
    uint64_t count;
} PDFRunEvidence;

typedef struct PDFPrefixScan {
    uint64_t length, stream_at, stream_len;
    bool flate, jpeg;
} PDFPrefixScan;

typedef struct PDFStreamSearch {
    uint32_t mode;
    uint64_t stream_at, hash, extra, slot, run;
    int64_t next_actual;
} PDFStreamSearch;

typedef struct PDFXrefAttempt PDFXrefAttempt;
typedef struct PDFObjectAttempt PDFObjectAttempt;

/* Deferred proposals own no decoded tables or candidate layouts. Physical
 * identity and /Prev survive compaction; search re-parses immutable indices. */
typedef struct PDFDeferredXref {
    uint64_t key, previous;
    int64_t head_actual;
    int32_t local;
} PDFDeferredXref;

typedef struct PDFCarveState{
    XrefTables *xref_tables;  // Points to linked list of XrefTables
    size_t num_tables;       // Number of xref tables found
    bool incomplete_obj;
    bool speculative_blocks;
    bool heuristic_blocks;
    bool xref_hypotheses_ambiguous;
    bool xref_identity_unresolved;
    uint64_t xref_identity_key;
    /* A completed original scan found this sole independently matching layout.
     * The evidence key binds the proof to the unchanged protected mapping. */
    uint64_t xref_identity_sole_key, xref_identity_sole_layout;
    uint64_t complete_layout_bytes;
    unsigned char complete_layout_digest[SHA256_DIGEST_LENGTH];
    bool complete_layout_ambiguous;
    PDFWeakXrefCursor weak_xref_cursor;
    PDFXrefAttempt *xref_attempt;
    bool xref_attempt_applied;
    PDFObjectAttempt *object_attempt;
    size_t xref_reject_count;
    uint64_t *xref_rejects;
    size_t deferred_xref_count;
    PDFDeferredXref *deferred_xrefs;
    // Linearization parameters, read once from the candidate's header block.
    // A linearized file places its entry-point xref at the FRONT, so its final
    // startxref does NOT locate the main table; lin_T does. See
    // pdf_detect_linearization().
    bool    linearized;      // /Linearized dict present as the first object
    bool first_page_prev_searched; // Strategy 2 completed for the original revision
    int64_t lin_L;           // /L: declared total length of that revision, -1 if absent
    int64_t lin_T;           // /T: offset of that revision's main xref, -1 if absent
    // Legacy local-retry fields: consumed on restore, then cleared.
    uint8_t backtrack_reject_count;
    PDFBacktrackChoice backtrack_rejects[PDF_BACKTRACK_MAX_REJECTIONS];
    PDFResume resume;
    // zero_search and mapped_search retain the old checkpoint layout only.
    PDFStreamSearch stream_search, zero_search, mapped_search, prefix_search;
    PDFPartialPrefix *partial_prefix;
    PDFStreamFailureCache *stream_failures; // Runtime only; no checkpoint layout change.
} PDFCarveState;

/* Immutable rollback mapping/state shared by ordinary carve-state snapshots. */
struct PDFXrefAttempt {
    atomic_uint references;
    PDFCarveState *before;
    uint64_t count, length, protected_length, best_validates_to, key, initial_key;
    int64_t *actual;
    Object *entries;
    int entry_count, block_count;
    int64_t *blocks;
    int64_t *block_slots; // Logical slot of each attributed xref block, or -1.
    int64_t slot;
    int32_t local;
    bool weak_attribution; // Rollback retries Strategy 3.2 for this attempt.
};
#define PDF_OBJECT_HEADER_BYTES UINT64_C(64)

/* Ambiguous object choices share metadata/mapping snapshots, never PDF bytes.
 * Parent nodes are immutable so ordinary state clones retain their own cursors. */
typedef struct PDFObjectPlan {
    atomic_uint references;
    PDFCarveState *before;
    uint64_t count, length, best_validates_to, slot, offset, xref_key;
    bool xref_applied;
    int object;
    size_t option_count;
    int64_t *actual;
    PDFObjectOption *options;
} PDFObjectPlan;

struct PDFObjectAttempt {
    atomic_uint references;
    PDFObjectPlan *plan;
    PDFObjectAttempt *parent;
    size_t selected;
};

typedef struct ZlibStreamReassembler {
    z_stream strm;           // current decompression state
    unsigned char *output;   // accumulated decompressed output
    size_t output_len;
    size_t output_capacity;
    // Declared /Length and bytes consumed: needed to reach Z_STREAM_END, where
    // zlib verifies the Adler-32 over the whole output -- DEFLATE's only integrity
    // check, since a wrong block otherwise decodes to plausible garbage.
    size_t stream_length;    // 0 = unknown, no completion gate
    size_t fed;              // bytes supplied from the declared stream extent
    int    ended;            // Z_STREAM_END reached
    int    pending_stream_prefix; // keyword tail + EOL precede data in next block
    PDFRC4State crypto;
    unsigned char *crypto_input;
    size_t crypto_input_capacity;
} ZlibStreamReassembler;

/*
 * Reassembler for uncompressed XML/XMP metadata streams. With no checksum to
 * validate blocks, acceptance is driven by the exact /Length, a per-byte
 * printable-text/UTF-8 gate, and an incremental XML structural state machine.
 * Scalar fields are snapshotted/restored by value on reject, so no checkpoint
 * clone is needed.
 */
typedef struct XmlStreamReassembler {
    unsigned char *output;       // accumulated stream bytes
    size_t output_len;           // bytes appended so far
    size_t output_capacity;
    size_t stream_length;        // exact expected /Length of the stream
    size_t fed;                  // stream bytes consumed by the state machine
    int    pending_stream_prefix;// keyword tail + EOL precede data in next block
    int    state;                // XmlScanState (see reconstruct path)
    int    just_opened;          // next byte is the first char after '<'
    int    prev_slash;           // previous in-tag char was '/' (for "/>")
    int    prev_q;               // previous in-PI char was '?' (for "?>")
    int    quote;                // inside a quoted attribute value: 0, '"' or '\''
    int    marker_run;           // trailing '-' (comment) or ']' (CDATA) run, capped at 2
    int    tag_depth;            // running element nesting depth
    int    malformed;            // structural/text violation seen
} XmlStreamReassembler;

/*
 * Reassembler for DCTDecode (JPEG) streams. Driven by the exact /Length and an
 * incremental state machine rather than a checksum, validating two regions: the
 * header/marker grammar (SOI -> APPn/DQT/DHT/SOF/DRI/SOS, with explicit segment
 * lengths) and the entropy-coded scan (the 0xFF byte-stuffing rule, plus the RSTn
 * cadence when a DRI restart interval is present). Completed assignments also
 * require full libjpeg decoding without warnings or repairs. init() preallocates
 * the full output capacity, so rejection rolls back with a by-value struct copy.
 */
typedef struct JpegStreamReassembler {
    unsigned char *output;       // accumulated stream bytes
    size_t output_len;           // bytes appended so far
    size_t output_capacity;
    size_t stream_length;        // exact expected /Length of the stream
    size_t fed;                  // stream bytes consumed by the state machine
    int pending_stream_prefix;   // keyword tail + EOL precede data in next block

    int state;                   // JpegScanState (see reconstruct path)
    int marker;                  // marker code of the segment being parsed
    int seg_len;                 // declared segment length (incl. 2 length bytes)
    int seg_remaining;           // payload bytes still to consume
    int prev_ff;                 // previous byte was 0xFF (marker/stuffing lead-in)

    int restart_interval;        // MCUs between RSTn (from DRI); 0 = none
    int expected_rst;            // next expected RSTn number (0..7), cycling
    int have_seen_rst;           // at least one RSTn cadence validated
    int dri_capture;             // currently reading the 2-byte DRI interval

    int saw_sos;                 // entered entropy scan at least once
    int saw_eoi;                 // EOI (FF D9) seen
    int malformed;               // grammar/stuffing/cadence violation seen

    // --- frame/table structure, used to validate segments against the spec ---
    size_t pos;                  // stream bytes fed so far; bounds segment lengths
    int saw_sof;                 // a frame header has been seen (exactly one is legal)
    int sof_marker;              // which SOFn defined the frame
    int precision;               // sample precision from SOF
    int frame_w, frame_h;        // image dimensions from SOF
    int ncomp;                   // component count from SOF
    unsigned dht_defined;        // Huffman tables defined, bit (class<<2)|id
    unsigned dqt_defined;        // quantisation tables defined, bit id
    int tbl_phase;               // DHT/DQT sub-parser: 0=header 1=counts 2=payload
    int tbl_id;                  // Tc/Th or Pq/Tq byte of the table being read
    int tbl_count;               // count bytes consumed (DHT)
    int tbl_total;               // sum of DHT counts = number of symbols
    int tbl_sym;                 // payload bytes still to consume for this table
    int scan_ncomp;              // component count of the current scan (SOS)
    int scan_count;              // scans seen
    bool decoded_complete;      // complete output decoded without warnings
} JpegStreamReassembler;

/* Incremental XML scan states for the metadata-stream reassembler. */
enum XmlScanState {
    X_TEXT,     // character data between tags
    X_OPEN,     // inside an opening/empty element tag "<name ...>"
    X_CLOSE,    // inside a closing tag "</name>"
    X_PI,       // inside a processing instruction "<? ... ?>"
    X_DECL,     // inside a declaration ending on '>' (e.g. "<!DOCTYPE ...>")
    X_BANG,     // just consumed "<!", deciding comment / CDATA / declaration
    X_BANG2,    // consumed "<!-", a comment needs a second '-'
    X_COMMENT,  // inside "<!-- ... -->" (content, incl. '<'/'>', is ignored)
    X_CDATA     // inside "<![CDATA[ ... ]]>" (content is character data)
};

/* Incremental marker/scan states for the JPEG (DCTDecode) reassembler. */
enum JpegScanState {
    J_START,    // expecting SOI (FF D8)
    J_MARKER,   // between segments: expecting FF then a marker code
    J_LEN1,     // reading high byte of a segment length
    J_LEN2,     // reading low byte of a segment length
    J_PAYLOAD,  // consuming a segment payload
    J_SCAN,     // entropy-coded scan data
    J_DONE      // EOI seen; stream complete
};

/* Physical xref markers are shared by all candidates for an image and needle.
 * Fixed-size chunks avoid copying the arrays as they grow. */
#define PDF_XREF_INDEX_CHUNK 4096
typedef struct PDFXrefTailIndexEntry {
    uint64_t actual;
    int32_t terminal_local;
    int8_t xref_type;
} PDFXrefTailIndexEntry;

typedef struct PDFSplitXrefRecord {
    int64_t head_actual;
    size_t block_offset;
    int32_t xref_local;
    uint32_t block_count;
    int8_t xref_type;
    Object *parsed_entries;
    int parsed_count;
} PDFSplitXrefRecord;

typedef struct PDFSplitXrefCatalog {
    PDFSplitXrefRecord *records;
    int64_t *actual_blocks;
    size_t record_count;
    size_t block_count;
    size_t parsed_bytes;
} PDFSplitXrefCatalog;

/* A start block is owned by one worker until completed or checkpointed.
 * Resume cursors use physical block numbers so blockmap swaps cannot invalidate
 * an unfinished search. This optional cache is rebuilt on process restore. */
typedef struct PDFIdentityRecord {
    struct PDFIdentityRecord *next;
    Object *entries;
    int64_t *blocks;
    int count, block_count;
    int32_t local;
    bool partial;
} PDFIdentityRecord;

typedef struct PDFSplitXrefJob {
    PDFResume resume;
    uint64_t retry_next;
    int32_t marker;
    PDFIdentityRecord *identity;
} PDFSplitXrefJob;

enum PDFSplitXrefCatalogState {
    PDF_SPLIT_XREF_UNBUILT,
    PDF_SPLIT_XREF_BUILDING,
    PDF_SPLIT_XREF_READY,
    PDF_SPLIT_XREF_UNAVAILABLE
};

/* One immutable lookup record for a block's cached first complete object. */
typedef struct PDFFirstObjectIndexEntry {
    uint64_t actual;
    int32_t first_obj;
} PDFFirstObjectIndexEntry;

typedef struct PDFEndstreamOffsetEntry {
    uint64_t node, actual;
} PDFEndstreamOffsetEntry;

typedef struct PDFXrefIndex {
    FileMirror *mirror;
    uint32_t needleidx;
    uint64_t next_actual, count;
    uint64_t **chunks;
    size_t chunk_count, chunk_capacity;
    PDFFirstObjectIndexEntry *object_entries;
    size_t object_count, object_capacity;
    bool object_unavailable;
    uint64_t tail_count;
    PDFXrefTailIndexEntry **tail_chunks;
    size_t tail_chunk_count, tail_chunk_capacity;
    PDFEndstreamOffsetEntry *offset_entries;
    size_t offset_count, offset_capacity;
    uint64_t offset_leaf;
    bool offset_unavailable;
    PDFSplitXrefCatalog *split_catalog;
    enum PDFSplitXrefCatalogState split_state;
    PDFSplitXrefJob *split_jobs;
    uint64_t split_next, split_retry, split_completed;
    uint32_t split_workers, split_peak_workers;
    bool identity_unavailable;
    uint64_t identity_bytes;
    size_t split_record_capacity, split_block_capacity;
    bool ready, unavailable;
    struct PDFXrefIndex *next;
} PDFXrefIndex;

