/* Resource/read failures are not exhaustive format evidence. */
static void pdf_identity_evidence_unavailable(void);
static void pdf_identity_evidence_unavailable(void) {
    if (pdf_collecting_split_index) {
        __atomic_store_n(&pdf_collecting_split_index->identity_unavailable, true,
            __ATOMIC_RELAXED);
    }
}

static void pdf_stream_failure_cancel(void) {
    pdf_identity_evidence_unavailable();

    if (pdf_identity_scan_complete) {
        *pdf_identity_scan_complete = false;
    }
    if(pdf_stream_failure_probe) {
        pdf_stream_failure_probe->valid = false;
    }
}

/* A rejected format trial is conclusive for that trial. Preserve the old
 * per-search cache invalidation without marking the physical catalog unreadable.
 * Resource failures continue through pdf_stream_failure_cancel directly. */
static void pdf_stream_format_rejected(void);
static void pdf_stream_format_rejected(void) {
    PDFXrefIndex *collecting = pdf_collecting_split_index;
    pdf_collecting_split_index = NULL;
    pdf_stream_failure_cancel();
    pdf_collecting_split_index = collecting;
}

static unsigned char *pdf_stream_read_block(FileMirror *mirror, int64_t apparent) {
    unsigned char *data = get_apparent_block_data(mirror, apparent);
    if(!data) {
        pdf_stream_failure_cancel();
    }
    return data;
}

/* Remember only candidate-dependent exclusions. Recheck them before reuse so
 * an object rollback or a released backend reservation can enable a new search. */
static void pdf_stream_failure_blocked(int64_t actual, bool occupied) {
    if (pdf_identity_scan_complete && !occupied) {

        *pdf_identity_scan_complete = false;
    }
    PDFStreamFailureProbe *probe = pdf_stream_failure_probe;
    if(!probe || !probe->valid) {
        return;
    }
    if(actual < 0 || (uint64_t)actual > UINT64_MAX / 2) {
        probe->valid = false;
        return;
    }
    uint64_t value = (uint64_t)actual * 2 + occupied;
    for(uint32_t i = 0; i < probe->entry.dependencies; i++) {
        if(probe->entry.blocked[i] == value) {
            return;
        }
    }
    if(probe->entry.dependencies == PDF_STREAM_FAILURE_DEPENDENCIES) {
        probe->valid = false;
        return;
    }
    probe->entry.blocked[probe->entry.dependencies++] = value;
}

static void pdf_stream_failure_release(PDFStreamFailureCache *cache) {
    if(cache && atomic_fetch_sub_explicit(&cache->references, 1,
                                          memory_order_acq_rel) == 1) {
        free(cache);
    }
}

static void pdf_stream_failure_inherit(PDFCarveState *to, const PDFCarveState *from) {
    pdf_stream_failure_release(to->stream_failures);
    to->stream_failures = from->stream_failures;
    if(to->stream_failures) {
        atomic_fetch_add_explicit(&to->stream_failures->references, 1,
                                  memory_order_relaxed);
    }
}

